def rrf(rankings: list[list[str]], k: int = 60) -> list[str]:
    """rankings = [bm25_doc_ids_ranked, dense_doc_ids_ranked, ...]"""
    scores = {}
    for ranking in rankings:
        for rank, doc_id in enumerate(ranking):
            scores[doc_id] = scores.get(doc_id, 0) + 1.0 / (k + rank + 1)
    return sorted(scores, key=scores.get, reverse=True)

# No score normalisation needed. No weight tuning. This is why RRF is
# the default in production hybrid search.

import numpy as np

def recall_at_k(retrieved: list[str], relevant: set[str], k: int) -> float:
    if not relevant: return 0.0
    return len(set(retrieved[:k]) & relevant) / len(relevant)

def mrr(retrieved: list[str], relevant: set[str]) -> float:
    """Reciprocal rank of the FIRST relevant hit. Rewards getting it right early."""
    for i, doc in enumerate(retrieved, start=1):
        if doc in relevant:
            return 1.0 / i
    return 0.0

def ndcg_at_k(retrieved: list[str], relevance: dict[str, float], k: int) -> float:
    """Graded relevance, discounted by log(rank). The metric interviewers ask about."""
    gains = [relevance.get(d, 0.0) for d in retrieved[:k]]
    dcg  = sum(g / np.log2(i + 2) for i, g in enumerate(gains))
    ideal = sorted(relevance.values(), reverse=True)[:k]
    idcg = sum(g / np.log2(i + 2) for i, g in enumerate(ideal))
    return dcg / idcg if idcg else 0.0

